<script setup lang="ts">
import { computed, watch } from 'vue'; import { useForm } from '@inertiajs/vue3';
export interface HostChoice { id: string; name: string; event_id: string; event_name: string; starts_at: string; ends_at: string }
export interface CategoryChoice { id: string; name: string; event_id: string }
export interface Guest { id: string; full_name: string; organisation: string | null; host_id: string; category_id: string; valid_from: string; valid_until: string; status: string }
const emit=defineEmits<{saved:[]}>();
const props=defineProps<{ hosts: HostChoice[]; categories: CategoryChoice[]; visitor?: Guest; locked?: boolean }>();
const iso=(v:string)=>new Date(v).toISOString().slice(0,16);
const first=props.hosts.find(h=>h.id===props.visitor?.host_id)||props.hosts[0];
const form=useForm({host_id:props.visitor?.host_id||first?.id||'',full_name:props.visitor?.full_name||'',organisation:props.visitor?.organisation||'',category_id:props.visitor?.category_id||props.categories.find(c=>c.event_id===first?.event_id)?.id||'',valid_from:props.visitor?iso(props.visitor.valid_from):first?iso(first.starts_at):'',valid_until:props.visitor?iso(props.visitor.valid_until):first?iso(first.ends_at):''});
const available=computed(()=>props.categories.filter(c=>c.event_id===props.hosts.find(h=>h.id===form.host_id)?.event_id));
watch(()=>form.host_id,()=>{if(props.visitor)return;const h=props.hosts.find(h=>h.id===form.host_id);form.category_id=available.value[0]?.id||'';if(h){form.valid_from=iso(h.starts_at);form.valid_until=iso(h.ends_at);}});
function submit(){if(props.visitor)form.put('/hote/invites/'+props.visitor.id);else form.post('/hote/invites',{onSuccess:()=>emit('saved')});}
</script>
<template><form class="space-y-5" :aria-label="visitor?'Modifier mon invité':'Ajouter un invité'" @submit.prevent="submit"><p v-if="locked" class="rounded border-2 border-ikoma-orange p-4">🔒 Invité déjà arrivé. Sa fiche ne peut plus être modifiée.</p><fieldset :disabled="locked || form.processing" class="space-y-5"><label class="block">Événement<select v-model="form.host_id" class="field" :disabled="!!visitor"><option v-for="host in hosts" :key="host.id" :value="host.id">{{ host.event_name }} · {{ host.name }}</option></select></label><label class="block">Nom complet<input v-model="form.full_name" class="field" required maxlength="160" /></label><label class="block">Organisation (facultative)<input v-model="form.organisation" class="field" maxlength="160" /></label><label class="block">Catégorie<select v-model="form.category_id" class="field" required><option v-for="c in available" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><p>Vous pouvez attribuer la catégorie Visiteur. Une catégorie déjà fixée par l’administration peut être conservée.</p><label class="block">Début de validité (UTC)<input v-model="form.valid_from" type="datetime-local" class="field" required /></label><label class="block">Fin de validité (UTC)<input v-model="form.valid_until" type="datetime-local" class="field" required /></label><button type="submit" class="btn-main" :disabled="locked || form.processing || !form.category_id">{{ visitor?'Enregistrer les modifications':'Ajouter cet invité' }}</button></fieldset><p v-for="(error,key) in form.errors" :key="key" role="alert" class="font-semibold text-red-900">{{ error }}</p></form></template>
